    fn predicate_condition(predicate: &UserPredicate) -> Condition {
        match predicate {
            UserPredicate::IdEq(value) => Condition::all().add(Column::Id.eq(*value)),
            UserPredicate::IdNe(value) => Condition::all().add(Column::Id.ne(*value)),
            UserPredicate::IdIn(values) => Condition::all().add(Column::Id.is_in(values.clone())),
            UserPredicate::IdNotIn(values) => {
                Condition::all().add(Column::Id.is_not_in(values.clone()))
            }
            UserPredicate::IdGt(value) => Condition::all().add(Column::Id.gt(*value)),
            UserPredicate::IdGte(value) => Condition::all().add(Column::Id.gte(*value)),
            UserPredicate::IdLt(value) => Condition::all().add(Column::Id.lt(*value)),
            UserPredicate::IdLte(value) => Condition::all().add(Column::Id.lte(*value)),
            UserPredicate::IdBetween(start, end) => {
                Condition::all().add(Column::Id.between(*start, *end))
            }
            UserPredicate::EmailEq(value) => Condition::all().add(Column::Email.eq(value.clone())),
            UserPredicate::EmailNe(value) => Condition::all().add(Column::Email.ne(value.clone())),
            UserPredicate::EmailIn(values) => {
                Condition::all().add(Column::Email.is_in(values.clone()))
            }
            UserPredicate::EmailNotIn(values) => {
                Condition::all().add(Column::Email.is_not_in(values.clone()))
            }
            UserPredicate::EmailContains(value) => {
                Condition::all().add(Column::Email.like(contains_like_pattern(value)))
            }
            UserPredicate::EmailNotContains(value) => Condition::all()
                .add(Column::Email.like(contains_like_pattern(value)))
                .not(),
            UserPredicate::EmailIContains(value) => Condition::all().add(
                Func::lower(Expr::col(Column::Email))
                    .like(contains_like_pattern(&value.to_lowercase())),
            ),
            UserPredicate::EmailNotIContains(value) => Condition::all()
                .add(
                    Func::lower(Expr::col(Column::Email))
                        .like(contains_like_pattern(&value.to_lowercase())),
                )
                .not(),
            UserPredicate::EmailEqualFold(value) => Condition::all().add(
                Func::lower(Expr::col(Column::Email))
                    .like(escape_like_pattern(&value.to_lowercase())),
            ),
            UserPredicate::EmailNotEqualFold(value) => Condition::all()
                .add(
                    Func::lower(Expr::col(Column::Email))
                        .like(escape_like_pattern(&value.to_lowercase())),
                )
                .not(),
            UserPredicate::EmailStartsWith(value) => {
                Condition::all().add(Column::Email.like(format!("{}%", escape_like_pattern(value))))
            }
            UserPredicate::EmailNotStartsWith(value) => Condition::all()
                .add(Column::Email.like(format!("{}%", escape_like_pattern(value))))
                .not(),
            UserPredicate::EmailEndsWith(value) => {
                Condition::all().add(Column::Email.like(format!("%{}", escape_like_pattern(value))))
            }
            UserPredicate::EmailNotEndsWith(value) => Condition::all()
                .add(Column::Email.like(format!("%{}", escape_like_pattern(value))))
                .not(),
            UserPredicate::NameEq(value) => Condition::all().add(Column::Name.eq(value.clone())),
            UserPredicate::NameNe(value) => Condition::all().add(Column::Name.ne(value.clone())),
            UserPredicate::NameIn(values) => {
                Condition::all().add(Column::Name.is_in(values.clone()))
            }
            UserPredicate::NameNotIn(values) => {
                Condition::all().add(Column::Name.is_not_in(values.clone()))
            }
            UserPredicate::NameContains(value) => {
                Condition::all().add(Column::Name.like(contains_like_pattern(value)))
            }
            UserPredicate::NameNotContains(value) => Condition::all()
                .add(Column::Name.like(contains_like_pattern(value)))
                .not(),
            UserPredicate::NameIContains(value) => Condition::all().add(
                Func::lower(Expr::col(Column::Name))
                    .like(contains_like_pattern(&value.to_lowercase())),
            ),
            UserPredicate::NameNotIContains(value) => Condition::all()
                .add(
                    Func::lower(Expr::col(Column::Name))
                        .like(contains_like_pattern(&value.to_lowercase())),
                )
                .not(),
            UserPredicate::NameEqualFold(value) => Condition::all().add(
                Func::lower(Expr::col(Column::Name))
                    .like(escape_like_pattern(&value.to_lowercase())),
            ),
            UserPredicate::NameNotEqualFold(value) => Condition::all()
                .add(
                    Func::lower(Expr::col(Column::Name))
                        .like(escape_like_pattern(&value.to_lowercase())),
                )
                .not(),
            UserPredicate::NameStartsWith(value) => {
                Condition::all().add(Column::Name.like(format!("{}%", escape_like_pattern(value))))
            }
            UserPredicate::NameNotStartsWith(value) => Condition::all()
                .add(Column::Name.like(format!("{}%", escape_like_pattern(value))))
                .not(),
            UserPredicate::NameEndsWith(value) => {
                Condition::all().add(Column::Name.like(format!("%{}", escape_like_pattern(value))))
            }
            UserPredicate::NameNotEndsWith(value) => Condition::all()
                .add(Column::Name.like(format!("%{}", escape_like_pattern(value))))
                .not(),
            UserPredicate::ActiveEq(value) => Condition::all().add(Column::Active.eq(*value)),
            UserPredicate::ActiveNe(value) => Condition::all().add(Column::Active.ne(*value)),
            UserPredicate::ActiveIn(values) => {
                Condition::all().add(Column::Active.is_in(values.clone()))
            }
            UserPredicate::ActiveNotIn(values) => {
                Condition::all().add(Column::Active.is_not_in(values.clone()))
            }
            UserPredicate::CreatedAtEq(value) => Condition::all().add(Column::CreatedAt.eq(*value)),
            UserPredicate::CreatedAtNe(value) => Condition::all().add(Column::CreatedAt.ne(*value)),
            UserPredicate::CreatedAtIn(values) => {
                Condition::all().add(Column::CreatedAt.is_in(values.clone()))
            }
            UserPredicate::CreatedAtNotIn(values) => {
                Condition::all().add(Column::CreatedAt.is_not_in(values.clone()))
            }
            UserPredicate::CreatedAtGt(value) => Condition::all().add(Column::CreatedAt.gt(*value)),
            UserPredicate::CreatedAtGte(value) => {
                Condition::all().add(Column::CreatedAt.gte(*value))
            }
            UserPredicate::CreatedAtLt(value) => Condition::all().add(Column::CreatedAt.lt(*value)),
            UserPredicate::CreatedAtLte(value) => {
                Condition::all().add(Column::CreatedAt.lte(*value))
            }
            UserPredicate::CreatedAtBetween(start, end) => {
                Condition::all().add(Column::CreatedAt.between(*start, *end))
            }
            UserPredicate::ManagerIdEq(value) => {
                Condition::all().add(Column::ManagerId.eq(Some(*value)))
            }
            UserPredicate::ManagerIdNe(value) => {
                Condition::all().add(Column::ManagerId.ne(Some(*value)))
            }
            UserPredicate::ManagerIdIsNull => Condition::all().add(Column::ManagerId.is_null()),
            UserPredicate::ManagerIdIsNotNull => {
                Condition::all().add(Column::ManagerId.is_not_null())
            }
            UserPredicate::ManagerIdIn(values) => Condition::all().add(
                Column::ManagerId
                    .is_in(values.iter().map(|value| Some(*value)).collect::<Vec<_>>()),
            ),
            UserPredicate::ManagerIdNotIn(values) => Condition::all().add(
                Column::ManagerId
                    .is_not_in(values.iter().map(|value| Some(*value)).collect::<Vec<_>>()),
            ),
            UserPredicate::ManagerIdGt(value) => {
                Condition::all().add(Column::ManagerId.gt(Some(*value)))
            }
            UserPredicate::ManagerIdGte(value) => {
                Condition::all().add(Column::ManagerId.gte(Some(*value)))
            }
            UserPredicate::ManagerIdLt(value) => {
                Condition::all().add(Column::ManagerId.lt(Some(*value)))
            }
            UserPredicate::ManagerIdLte(value) => {
                Condition::all().add(Column::ManagerId.lte(Some(*value)))
            }
            UserPredicate::ManagerIdBetween(start, end) => {
                Condition::all().add(Column::ManagerId.between(Some(*start), Some(*end)))
            }
            UserPredicate::And(predicates) => predicates
                .iter()
                .fold(Condition::all(), |condition, predicate| {
                    condition.add(Self::predicate_condition(predicate))
                }),
            UserPredicate::Or(predicates) => predicates
                .iter()
                .fold(Condition::any(), |condition, predicate| {
                    condition.add(Self::predicate_condition(predicate))
                }),
            UserPredicate::Not(predicate) => Condition::all()
                .add(Self::predicate_condition(predicate))
                .not(),
        }
    }

    fn build_filter_select(&self) -> Select<Entity> {
        let mut select = Entity::find();
        for predicate in &self.predicates {
            select = select.filter(Self::predicate_condition(predicate));
        }
        select
    }

    fn apply_order(&self, mut select: Select<Entity>) -> Select<Entity> {
        for order in &self.orders {
            match order {
                UserOrder::IdAsc => select = select.order_by_asc(Column::Id),
                UserOrder::IdDesc => select = select.order_by_desc(Column::Id),
                UserOrder::EmailAsc => select = select.order_by_asc(Column::Email),
                UserOrder::EmailDesc => select = select.order_by_desc(Column::Email),
                UserOrder::NameAsc => select = select.order_by_asc(Column::Name),
                UserOrder::NameDesc => select = select.order_by_desc(Column::Name),
                UserOrder::ActiveAsc => select = select.order_by_asc(Column::Active),
                UserOrder::ActiveDesc => select = select.order_by_desc(Column::Active),
                UserOrder::CreatedAtAsc => select = select.order_by_asc(Column::CreatedAt),
                UserOrder::CreatedAtDesc => select = select.order_by_desc(Column::CreatedAt),
                UserOrder::ManagerIdAsc => select = select.order_by_asc(Column::ManagerId),
                UserOrder::ManagerIdDesc => select = select.order_by_desc(Column::ManagerId),
            }
        }
        select
    }

    fn build_select(&self) -> Select<Entity> {
        let mut select = self.apply_order(self.build_filter_select());
        if let Some(limit) = self.limit {
            select = select.limit(limit);
        }
        if let Some(offset) = self.offset {
            select = select.offset(offset);
        }
        select
    }

    /// Converts this typed query into the backend-native SeaORM select.
    /// Predicates, soft-delete scope, ordering and pagination are preserved.
    pub fn into_select(self) -> Select<Entity> {
        self.build_select()
    }

    #[allow(clippy::clone_on_copy)]
    pub async fn all_with_groups(
        self,
        through_repo: &crate::model::MembershipRepository<'_>,
        repo: &crate::model::GroupRepository<'_>,
    ) -> anyhow::Result<Vec<UserWithGroups>> {
        let nodes = self.all().await?;
        let values = nodes.iter().map(|node| node.id.clone()).collect::<Vec<_>>();
        let joins = through_repo
            .query()
            .where_(crate::model::membership::user_id_in(values))
            .all()
            .await?;
        let target_values = joins
            .iter()
            .map(|join| join.group_id.clone())
            .collect::<Vec<_>>();
        let targets = repo
            .query()
            .where_(crate::model::group::id_in(target_values))
            .all()
            .await?;
        let mut loaded = Vec::with_capacity(nodes.len());
        for node in nodes {
            let target_values = joins
                .iter()
                .filter(|join| join.user_id == node.id)
                .map(|join| &join.group_id)
                .collect::<Vec<_>>();
            let edge = targets
                .iter()
                .filter(|target| target_values.contains(&&target.id))
                .cloned()
                .collect();
            loaded.push(UserWithGroups { node, edge });
        }
        Ok(loaded)
    }

